<template>
  <div class="chart-card">
    <div class="chart-header">
      <div>
        <div class="chart-tag">{{ $t('metrics.check') }}</div>
        <h2 class="chart-title">{{ $t('charts.checkManagersTitle') }}</h2>
        <p class="chart-subtitle">{{ period }}</p>
      </div>
    </div>
    <div class="cr-legend">
      <div class="cr-leg-item">
        <div class="cr-leg-dot" style="background:#6366f1"></div>{{ $t('charts.factLabel') }}
      </div>
      <div class="cr-leg-item">
        <div class="cr-leg-dot" style="background:rgba(99,102,241,.2);border:1.5px dashed #6366f155"></div>{{ $t('common.plan') }}
      </div>
      <div class="cr-leg-item">
        <div class="cr-leg-dot" style="background:#e2e8f0"></div>{{ $t('charts.lastYearLabel') }}
      </div>
    </div>
    <div class="check-rows">
      <div v-for="m in managers" :key="m.name" class="check-row">
        <div class="cr-name">{{ m.name }}</div>
        <div class="cr-bars">
          <div class="cr-bar-wrap">
            <div class="cr-bar" :style="{ width: barW(m.check_f), background: m.color + 'dd' }"></div>
            <span class="cr-bar-label" :style="{ color: m.color }">
              {{ m.check_f.toLocaleString('ru-RU') }}
            </span>
          </div>
          <div class="cr-bar-wrap">
            <div class="cr-bar" :style="{ width: barW(m.check_p), background: 'rgba(99,102,241,.15)', border: '1.5px dashed rgba(99,102,241,.35)' }"></div>
            <span class="cr-bar-label" style="color:#94a3b8">{{ m.check_p.toLocaleString('ru-RU') }}</span>
          </div>
          <div class="cr-bar-wrap">
            <div class="cr-bar" :style="{ width: barW(m.check_past), background: '#e2e8f0' }"></div>
            <span class="cr-bar-label" style="color:#94a3b8">{{ m.check_past.toLocaleString('ru-RU') }}</span>
          </div>
        </div>
        <div class="cr-pct" :style="{ color: pctColor(m.pct) }">{{ m.pct }}%</div>
      </div>
    </div>
  </div>
</template>

<script>
import { dataStore } from '@/operations/requests'
import { MANAGERS, getManagerColor } from '@/config/managers.config'

function pctColor(p) {
  if (p >= 100) return '#22c55e'
  if (p >= 90)  return '#84cc16'
  if (p >= 80)  return '#f59e0b'
  if (p >= 70)  return '#f97316'
  return '#ef4444'
}

export default {
  name: 'CheckManagersChart',

  props: {
    selectedDate: {
      type: String,
      default: '',
    },
  },

  data() {
    return {
      managers: [],
      period:   '',
      maxVal:   0,
    }
  },

  mounted() {
    this.setData()
  },

  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.setData()
      }
    },
  },

  methods: {
    setData() {
      const sources = MANAGERS.map(m => ({
        name: m.name,
        data: dataStore.getManagerData(m.id),
      }))

      const result = sources
          .filter(s => s.data && s.data.length)
          .map(s => {
            // Ищем строку по выбранной дате, если дата не выбрана — берём первую
            const row = this.selectedDate
                ? s.data.find(item => item.time === this.selectedDate)
                : s.data[0]

            if (!row) return null

            const pct = row.check_p
                ? Math.round((row.check_f / row.check_p) * 1000) / 10
                : 0

            return {
              name:       s.name,
              color:      getManagerColor(s.name),
              check_f:    row.check_f    ?? 0,
              check_p:    row.check_p    ?? 0,
              check_past: row.check_past  ?? 0,
              pct,
            }
          })
          .filter(Boolean) // убираем null если дата не найдена у менеджера

      this.managers = result.sort((a, b) => b.check_f - a.check_f)
      this.period   = this.selectedDate || ''
      this.maxVal   = result.length
          ? Math.max(...result.flatMap(m => [m.check_f, m.check_p, m.check_past])) * 1.1
          : 0
    },

    barW(val) {
      return Math.min((val / this.maxVal) * 100, 100) + '%'
    },

    pctColor,
  },
}
</script>

