<template>
  <div class="chart-card">
    <div class="chart-header">
      <div>
        <div class="chart-tag">{{ $t('metrics.conversion') }}</div>
        <h2 class="chart-title">{{ $t('charts.conversionManagersTitle') }}</h2>
        <p class="chart-subtitle">{{ period }}</p>
      </div>
    </div>
    <div class="conv-legend">
      <div class="conv-leg-item">
        <span class="leg-dot-fact"></span>{{ $t('charts.factLabel') }}
      </div>
      <div class="conv-leg-item">
        <span class="leg-dot-past"></span>{{ $t('charts.lastYearLabel') }}
      </div>
      <div class="conv-leg-item">
        <span class="leg-plan-line"></span>{{ $t('common.plan') }}
      </div>
    </div>
    <div class="conv-rows">
      <div v-for="m in managers" :key="m.name" class="conv-row">
        <div class="conv-name">{{ m.name }}</div>
        <div class="conv-col">
          <div class="conv-track">
            <!-- Залив до факта -->
            <div
                class="conv-fill"
                :style="{ width: toLeft(m.conver_f), background: m.color + '22' }"
            ></div>
            <!-- Линия плана -->
            <div class="conv-plan-line" :style="{ left: toLeft(m.conver_p) }">
              <span class="conv-plan-tip">{{ m.conver_p }}%</span>
            </div>
            <!-- Точка прошлого года -->
            <div
                class="conv-past-dot"
                :style="{ left: toLeft(m.conver_past), background: m.color }"
                
            ></div>
            <!-- Точка факта -->
            <div
                class="conv-fact-dot"
                :style="{ left: toLeft(m.conver_f), background: m.color }"
            >
              <span class="conv-fact-val">{{ m.conver_f }}</span>
            </div>
          </div>
          <!-- Подпись -->
          <div class="conv-footer">
            <span class="conv-footer-left">0%</span>
            <span class="conv-footer-pct" :style="{ color: pctColor(m.pct) }">
              {{ m.pct >= 100 ? '▲' : '▼' }} {{ m.pct }}% {{ $t('charts.fromPlan') }}
            </span>
            <span class="conv-footer-right">{{ maxConv }}%</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import {dataStore} from '@/operations/requests'
import { MANAGERS, getManagerColor } from '@/config/managers.config'
function pctColor(p) {
  if (p >= 100) return '#22c55e'
  if (p >= 90)  return '#84cc16'
  if (p >= 80)  return '#f59e0b'
  if (p >= 70)  return '#f97316'
  return '#ef4444'
}

export default {
  name: 'ConverciaManagersChart',
  props: {
    selectedDate: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      managers: [],
      period: '',
      maxConv: 20,
    }
  },
  mounted() {
    this.setData()
  },
  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.setData()
      }
    },
  },
  methods: {
    setData() {
      const sources = MANAGERS.map(m => ({
        name: m.name,
        data: dataStore.getManagerData(m.id),
      }))

      const result = sources
          .filter(s => Array.isArray(s.data) && s.data.length)
          .map(s => {
            const row = this.selectedDate
                ? s.data.find(item => item.time === this.selectedDate)
                : s.data[0]

            if (!row) return null

            const pct = row.conver_p
                ? Math.round((row.conver_f / row.conver_p) * 1000) / 10
                : 0

            return {
              name: s.name,
              color: getManagerColor(s.name),
              conver_f: row.conver_f ?? 0,
              conver_p: row.conver_p ?? 0,
              conver_past: row.conver_past ?? 0,
              pct,
            }
          })
          .filter(Boolean)

      const allVals = result.flatMap(m => [m.conver_f, m.conver_p, m.conver_past])
      this.maxConv = allVals.length ? Math.ceil(Math.max(...allVals) * 1.2) : 20
      this.managers = result.sort((a, b) => b.conver_f - a.conver_f)
      this.period = this.selectedDate || ''
    },

    toLeft(val) {
      if (!this.maxConv) return '0%'
      return Math.min((val / this.maxConv) * 100, 100) + '%'
    },

    pctColor,
  },
}
</script>

